#include <stdio.h>
#include <cuda_runtime.h>
#include <curand_kernel.h>

#define N 1000000       // number of RNG states / threads
#define NUM_RANDS 100   // random numbers generated by each thread

// device api - init + run


// xorwow

// x ^= x << a 
// + C mod 2^32 (C is odd)

__global__ void init_xorwow(curandStateXORWOW_t* states) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;

    if (i < N) {
        curand_init(1234, i, 0, &states[i]);
    }
}

__global__ void run_xorwow(curandStateXORWOW_t* states, float* out) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;

    if (i < N) {
        curandStateXORWOW_t local = states[i];

        float sum = 0.0f;

        for (int j = 0; j < NUM_RANDS; j++) {
            sum += curand_uniform(&local);
        }

        states[i] = local;

        // make sure compiler cannot throw away the RNG work
        out[i] = sum;
    }
}



// philox

// f(counter, key)
// f - permutation / scramble
    // x0, x1, x2, x3 / constants M0 M1
    // P0 = M0 * x0 = (lo0, hi0)
    // P1 = M1 * x1 = (lo1, hi1)

    // scramble / xor - key / hi / lo / x

// 4 counters / 32 bit

__global__ void init_philox(curandStatePhilox4_32_10_t* states) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;

    if (i < N) {
        curand_init(1234, i, 0, &states[i]);
    }
}


__global__ void run_philox(curandStatePhilox4_32_10_t* states, float* out) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;

    if (i < N) {
        curandStatePhilox4_32_10_t local = states[i];

        float sum = 0.0f;

        for (int j = 0; j < NUM_RANDS; j++) {
            sum += curand_uniform(&local);
        }

        states[i] = local;
        out[i] = sum;
    }
}




// MRG32k3a

// xn = (a * x_n-2 - b * x_n-3) mod m1
// yn = (c * y_n-1 - d * y_n-3) mod m2

// 2 generator - longer period - 2^191

// need to store x[n-3:n], y[n-3:n]

__global__ void init_mrg(curandStateMRG32k3a_t* states) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;

    if (i < N) {
        curand_init(1234, i, 0, &states[i]);
    }
}


__global__ void run_mrg(curandStateMRG32k3a_t* states, float* out) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;

    if (i < N) {
        curandStateMRG32k3a_t local = states[i];

        float sum = 0.0f;

        for (int j = 0; j < NUM_RANDS; j++) {
            sum += curand_uniform(&local);
        }

        states[i] = local;
        out[i] = sum;
    }
}






int main() {

    int threads = 256;
    int blocks = (N + threads - 1) / threads;

    float* d_out;
    cudaMalloc(&d_out, N * sizeof(float));


    // xorwow

    curandStateXORWOW_t* xorwow_states;
    cudaMalloc(&xorwow_states, N * sizeof(curandStateXORWOW_t));

    init_xorwow<<<blocks, threads>>>(xorwow_states);
    cudaDeviceSynchronize();

    run_xorwow<<<blocks, threads>>>(xorwow_states, d_out);
    cudaDeviceSynchronize();

    cudaFree(xorwow_states);


    // philox

    curandStatePhilox4_32_10_t* philox_states;
    cudaMalloc(&philox_states, N * sizeof(curandStatePhilox4_32_10_t));

    init_philox<<<blocks, threads>>>(philox_states);
    cudaDeviceSynchronize();

    run_philox<<<blocks, threads>>>(philox_states, d_out);
    cudaDeviceSynchronize();

    cudaFree(philox_states);


    // MRG32k3a

    curandStateMRG32k3a_t* mrg_states;
    cudaMalloc(&mrg_states, N * sizeof(curandStateMRG32k3a_t));

    init_mrg<<<blocks, threads>>>(mrg_states);
    cudaDeviceSynchronize();

    run_mrg<<<blocks, threads>>>(mrg_states, d_out);
    cudaDeviceSynchronize();

    cudaFree(mrg_states);


    cudaFree(d_out);

    return 0;
}